import fs from 'node:fs';
const p=new URL('./news-20261118.json',import.meta.url);
const data=JSON.parse(fs.readFileSync(p,'utf8'));
const additions={
beijing:'同名文件再次收到时，先核对页数和可见内容，再判断是副本还是补充材料。不要仅凭名称相同就覆盖旧文件，来源关系应在目录里留下记录。',
chengdu:'日程本上日期格子也可能只是预印格式，并不能单独证明字写于那一天。遇到跨日记录或后补内容，目录中分开说明，原图不重新排版。',
chongqing:'若装订边有无法展开的小字，可先标明遮挡区域，后续交接时专门提出。不能读到的内容不需要为了清单完整而猜着录入。',
guangzhou:'纸张型号只有提供者确认或实物可核对时才记录。页面比例不明确的图片，可以用于定位文字，但实际尺寸应暂时留空。',
hangzhou:'同一个括号是否属于正文，有时需要结合前后几行阅读。提供者另有说明时附在目录，不把说明文字直接添加进原图充作手稿内容。',
nanjing:'图像中出现细小白边或黑边，可能与增强有关。可以把具体位置列出来等待核查，不要仅依据这种边缘外观推断纸上曾经重描。',
shanghai:'缺失的页首可能包含标题、称呼或其他文字，当前看不到就不能下定论。截取范围与原件是否仍在，分别记录，便于针对性补充。',
shenzhen:'有些手机保存了可调整的景深版本，也可能只剩导出的照片。是否还能恢复要根据实际文件核实，不承诺用后期软件一定找回被虚化的字。',
suzhou:'不同信纸的横线间距未必相同。即使屏幕上看着接近，也不能先把格线调成等宽，再据此判断文字实际大小是否一致。',
tianjin:'如果某次姓名确实模糊，可以在目录中注明局部不可辨。另一处更清楚的落款提供的是另一份观察位置，不能代替模糊处本来存在的形态。',
wuhan:'当提供者后来确认某段是补记，应追加说明和确认来源，而不是改掉原来的接收记录。资料更新过程本身也需要保持前后对应。',
xian:'同一页正反面如能配套保存，可各设子编号。无法确认是否属于同一张纸时，先保留为待核对关系，不因纸色相近就直接合并。'
};
for(const d of data){const text=additions[d.slug];if(text&&!d.sections[0][1].includes(text))d.sections[0][1]+=text;}
fs.writeFileSync(p,JSON.stringify(data,null,2)+'\n');
